import sys

def solve1(n, m, a):
	s = 0
	ok = False
	for i in a:
		v = i // m
		if v >= 2:
			s += v
			if v > 2:
				ok = True
	if ok:
		return s >= n
	else:
		return s >= n and n % 2 == 0

def solve():
	inp = sys.stdin.readline
	(n, m, k) = map(int, inp().split())
	a = list(map(int, inp().split()))
	if solve1(n, m, a) or solve1(m, n, a):
		print('Yes')
	else:
		print('No')

def main():
	for i in range(int(sys.stdin.readline())):
		solve()
main()
